function d_patent_claim(P,R){var indep=P.independent||1,dep=P.dependent||4,claims=[];for(var i=0;i<indep;i++)claims.push({n:i+1,type:'independent',text:'A system comprising '+P.elements[i%P.elements.length]+' ...'});for(var j=0;j<dep;j++)claims.push({n:indep+j+1,type:'dependent',depends_on:1+(j%indep),text:'The system of claim '+(1+(j%indep))+' wherein ...'});return{title:P.title,claims:claims,antecedent_ok:true};}

