function d_prior_art(P,R){var docs=P.docs||[];var q=(P.query||'').toLowerCase().split(/\s+/);var sc=docs.map(function(d){var t=(d.title+' '+d.abstract).toLowerCase().split(/\s+/);var hit=q.filter(function(w){return t.indexOf(w)>=0;}).length;return{id:d.id,title:d.title,jaccard:+(hit/Math.max(1,q.length)).toFixed(3)};});sc.sort(function(a,b){return b.jaccard-a.jaccard;});return{query:P.query,top:sc.slice(0,3),searched:docs.length};}

